import { useEffect, useState } from 'react';

// Lightweight i18n for the owner dashboard + customer PWA. Nav chrome and page
// bodies (headings, buttons, form labels/placeholders, table headers, status &
// enum labels, empty states and common inline messages) are covered. Adding a
// regional language is just another block in DICT (nav keys below) and PAGE
// (page-body keys further down) plus a row in LANGS; every t() call and the
// language switch pick it up automatically.
//
// Note: the ta/te/kn/ml/ur page-body translations are standard UI terms and
// still want a native-speaker QA pass before a wide regional rollout.

// English + Hindi + the four major South Indian (Dravidian) languages. Each
// language is one row here plus one block in DICT below; the nav labels and the
// language switch pick it up automatically. Nav-label translations are standard
// UI terms — worth a native-speaker QA pass before a wide regional rollout.
export const LANGS = [
  { code: 'en', label: 'EN', name: 'English' },
  { code: 'hi', label: 'हिं', name: 'हिन्दी' },
  { code: 'ta', label: 'த', name: 'தமிழ்' },
  { code: 'te', label: 'తె', name: 'తెలుగు' },
  { code: 'kn', label: 'ಕ', name: 'ಕನ್ನಡ' },
  { code: 'ml', label: 'മ', name: 'മലയാളം' },
  { code: 'ur', label: 'اردو', name: 'اردو', rtl: true },
];

// Languages that read right-to-left. The app sets dir="rtl" on <html> for these.
// RTL_LANGS is the built-in fallback used before the active registry resolves
// (and offline); once loaded, the chosen language's rtl flag comes from the
// active list (getActiveLanguages) so a newly activated RTL language is honoured
// without a code change.
export const RTL_LANGS = new Set(LANGS.filter((l) => l.rtl).map((l) => l.code));
export function isRtl(lang) {
  const found = getActiveLanguages().find((l) => l.code === lang);
  if (found) return !!found.rtl;
  return RTL_LANGS.has(lang);
}

