    'stmt.date': 'तारीख',
    'stmt.shop': 'दुकान',
    'stmt.rangeError': '"से" तारीख "तक" तारीख से पहले या समान होनी चाहिए।',
    'stmt.customerStatement': 'ग्राहक विवरण',
    'stmt.loadError': 'विवरण लोड नहीं हो सका।',
    'stmt.combined': 'संयुक्त कुल',
    'help.title': 'सहायता और सामान्य प्रश्न',
    'help.subtitle': 'सबसे आम कामों के लिए छोटे तरीके।',
    'help.manualLink': 'अधिक जानकारी के लिए पूरा उपयोगकर्ता मैनुअल और FAQ पढ़ें।',
    'help.e1.q': 'ग्राहक कैसे जोड़ें?',
    'help.e1.a': 'ग्राहक खोलें, जोड़ें दबाएँ, और नाम व फ़ोन डालें। क्रेडिट सीमा वैकल्पिक है — 0 का मतलब कोई सीमा नहीं।',
    'help.e2.q': 'उधार (क्रेडिट बिक्री) कैसे दर्ज करें?',
    'help.e2.a': 'ग्राहक खोलें, खरीद चुनें, राशि डालें और सहेजें। उनका शेष उतना बढ़ जाता है।',
    'help.e3.q': 'भुगतान कैसे लें?',
    'help.e3.a': 'ग्राहक खोलें, नकद या UPI चुनें, प्राप्त राशि डालें और सहेजें। उनका शेष घट जाता है।',
    'help.e4.q': 'रिमाइंडर कैसे काम करते हैं?',
    'help.e4.a': 'आपकी दुकान के नोटिफ़िकेशन मोड के अनुसार विनम्र व्हाट्सऐप रिमाइंडर भेजे जाते हैं। किसी भी एक ग्राहक के लिए इन्हें बंद कर सकते हैं।',
    'help.e5.q': 'कैटलॉग से आइटम कैसे जोड़ें?',
    'help.e5.a': 'कैटलॉग में साझा मास्टर कैटलॉग खोजें, आइटम अपनी दुकान में जोड़ें, फिर अपना दाम तय करें।',
    'help.e6.q': 'वजन के हिसाब से खुला सामान कैसे बेचें?',
    'help.e6.a': 'उत्पाद को वजन के हिसाब से बिकने वाला चिह्नित करें और प्रति किलो दाम तय करें। चुने गए वजन का दाम अपने आप निकल जाता है।',
    'help.e7.q': 'अपनी दुकान ग्राहकों के साथ कैसे साझा करें?',
    'help.e7.a': 'सेटिंग्स में "अपनी दुकान साझा करें" से लिंक कॉपी करें या काउंटर के लिए QR कोड प्रिंट करें। ग्राहक बिना लॉगिन देख सकते हैं।',
    'help.e8.q': 'क्या यह बिना इंटरनेट के काम करता है?',
    'help.e8.a': 'हाँ। ऑफ़लाइन की गई प्रविष्टियाँ आपके फ़ोन में सहेजी जाती हैं और ऑनलाइन होते ही अपने आप सिंक हो जाती हैं।',
    'help.e9.q': 'भाषा कैसे बदलें?',
    'help.e9.a': 'स्क्रीन के ऊपर भाषा स्विच का उपयोग करें। आपकी पसंद इस डिवाइस पर याद रहती है।',
    'help.e10.q': 'डेटा-सेवर मोड क्या है?',
    'help.e10.a': 'डेटा-सेवर धीमे या महँगे कनेक्शन के लिए छवियाँ और डेटा उपयोग घटाता है। इसे सेटिंग्स या अपने खाते पेज से चालू करें।',
    'help.e11.q': 'प्लान में क्या शामिल है?',
    'help.e11.a': 'फ्री प्लान रोज़मर्रा के खाते के लिए है। सशुल्क प्लान सीमाएँ बढ़ाते हैं और सुविधाएँ जोड़ते हैं। तुलना और बदलाव के लिए सेटिंग्स देखें।',
    'help.e12.q': 'खाता विवरण कैसे लें?',
    'help.e12.a': 'खाता विवरण टूल से तारीख अवधि चुनें, प्रविष्टियाँ देखें, और CSV डाउनलोड करें या प्रिंट करें।',
    'help.e13.q': 'क्या मेरा ईमेल, लिंग और जन्मतिथि ज़रूरी है?',
    'help.e13.a': 'नहीं। ये वैकल्पिक और निजी हैं। इन्हें खाली छोड़कर भी आप हर सुविधा का उपयोग कर सकते हैं।',
