// Merge page-body keys into the per-language DICT blocks. Nav keys defined in
// DICT stay authoritative; PAGE only adds new keys.
for (const code of Object.keys(PAGE)) {
  if (!DICT[code]) DICT[code] = {};
  Object.assign(DICT[code], PAGE[code]);
}

// Merge the admin language-registry UI strings the same way.
for (const code of Object.keys(ALANG)) {
  if (!DICT[code]) DICT[code] = {};
  Object.assign(DICT[code], ALANG[code]);
}

// Merge the admin RBAC + moderation UI strings the same way.
for (const code of Object.keys(MOD)) {
  if (!DICT[code]) DICT[code] = {};
  Object.assign(DICT[code], MOD[code]);
}

// Merge the referrals / onboarding-source UI strings the same way.
for (const code of Object.keys(REF)) {
  if (!DICT[code]) DICT[code] = {};
  Object.assign(DICT[code], REF[code]);
}

// Merge the role-based downloads UI strings the same way.
for (const code of Object.keys(DL)) {
  if (!DICT[code]) DICT[code] = {};
  Object.assign(DICT[code], DL[code]);
}

// Merge the Control-Room dashboard + insights UI strings the same way.
for (const code of Object.keys(DASH)) {
  if (!DICT[code]) DICT[code] = {};
  Object.assign(DICT[code], DASH[code]);
}

// Merge the Owner Help "Today at your shop" nudge strings the same way.
for (const code of Object.keys(OWN)) {
  if (!DICT[code]) DICT[code] = {};
  Object.assign(DICT[code], OWN[code]);
}

// The English plural suffix token {s} (e.g. "{n} item{s}") has no equivalent in
// the other languages' wording here, so strip it from their strings — English
// keeps it and receives 's'/'' at call time; every other language ignores the
// unused `s` var and renders without the token.
for (const code of Object.keys(DICT)) {
  if (code === 'en') continue;
  for (const k of Object.keys(DICT[code])) {
    if (typeof DICT[code][k] === 'string' && DICT[code][k].includes('{s}')) {
      DICT[code][k] = DICT[code][k].replace(/\{s\}/g, '');
    }
  }
}

const KEY = 'skhata_lang';
const CHOSEN_KEY = 'skhata_lang_set';
const EVENT = 'skhata-lang';
const OVERRIDE_EVENT = 'skhata-i18n';

// Live translation overrides fetched from the backend at runtime, shaped as
// { lang: { key: value, ... }, ... }. Layered on top of the static DICT below.
// Starts EMPTY so SSR and the first client render are identical (hydration-safe);
// loadOverrides() fills it after mount, then dispatches OVERRIDE_EVENT so mounted
// useLang() consumers re-render with the corrected strings.
let OVERRIDES = {};

// Fetch the current overrides from the public endpoint and apply them app-wide.
// Errors are swallowed (offline / API down → just use the static dict).
export async function loadOverrides() {
  try {
    const base = (typeof process !== 'undefined' && process.env.NEXT_PUBLIC_API_URL) || '';
    const res = await fetch(`${base}/api/i18n/overrides`);
    if (!res.ok) return;
    const data = await res.json();
    OVERRIDES = (data && data.overrides) || {};
    if (typeof window !== 'undefined') window.dispatchEvent(new Event(OVERRIDE_EVENT));
  } catch {
    /* offline / fetch blocked — keep static dict */
  }
}

// Helpers for the admin review UI. The key CATALOG and built-in text live in the
// frontend DICT; these read straight from it (plus the live overrides).
export function getAllKeys() {
  return Object.keys(DICT.en).sort();
}
export function staticValue(lang, key) {
  return (DICT[lang] && DICT[lang][key]) || '';
}
export function getOverrideValue(lang, key) {
  return (OVERRIDES[lang] && OVERRIDES[lang][key]) || '';
}

// ---- Active language registry (Phase B) ---------------------------------
// Which languages are SHOWN comes from the DB registry via
// /api/public/languages. The built-in LANGS below stays as the offline /
// first-paint fallback, and the string catalog (DICT) is untouched — the
// registry only decides visibility. Activating a staged language degrades
// gracefully to English (translate() falls back) until its strings are added.
const ACTIVE_EVENT = 'skhata-langs';

// Null until loadActiveLanguages() resolves, so getActiveLanguages() falls back
// to the built-in LANGS (the current 7) and the picker/gate ALWAYS work offline
// or before the API answers.
let ACTIVE_LANGS = null;

// Fetch the active languages and cache them app-wide. Normalised to the LANGS
// shape ({ code, label, name, rtl }) so the picker and gate iterate identically.
// Errors and empty/blank responses are swallowed — we never blank the picker.
export async function loadActiveLanguages() {
  try {
    const base = (typeof process !== 'undefined' && process.env.NEXT_PUBLIC_API_URL) || '';
    const res = await fetch(`${base}/api/public/languages`);
    if (!res.ok) return;
    const data = await res.json();
    const list = (data && data.languages) || [];
    if (!Array.isArray(list) || list.length === 0) return; // keep the fallback
    ACTIVE_LANGS = list.map((l) => ({
      code: l.code,
      // The registry's native label is what the picker shows (LANGS uses `name`).
      name: l.label,
      label: l.label,
      rtl: !!l.rtl,
    }));
    if (typeof window !== 'undefined') window.dispatchEvent(new Event(ACTIVE_EVENT));
  } catch {
    /* offline / fetch blocked / not seeded — keep the built-in LANGS */
  }
}

// The languages to SHOW: the fetched active set, or the built-in LANGS when the
// fetch hasn't resolved or failed — so the picker/gate ALWAYS render something.
export function getActiveLanguages() {
  return ACTIVE_LANGS && ACTIVE_LANGS.length ? ACTIVE_LANGS : LANGS;
}

// Hook returning the active language list, re-rendering when it loads/changes.
// First render (SSR + client) is always the built-in LANGS, so hydration never
// mismatches; the fetched list applies right after it resolves.
export function useActiveLanguages() {
  const [list, setList] = useState(getActiveLanguages());
  useEffect(() => {
    setList(getActiveLanguages());
    const on = () => setList(getActiveLanguages());
    window.addEventListener(ACTIVE_EVENT, on);
    return () => window.removeEventListener(ACTIVE_EVENT, on);
  }, []);
  return list;
}

export function getLang() {
  if (typeof window === 'undefined') return 'en';
  try {
    const v = window.localStorage.getItem(KEY);
    return DICT[v] ? v : 'en';
  } catch {
    return 'en';
  }
}

// Whether the viewer has EXPLICITLY picked a language (via the first-open gate
// or the switcher) — distinct from the 'en' default. Drives the one-time
// language prompt on the customer app.
export function hasChosenLang() {
  if (typeof window === 'undefined') return true; // never gate during SSR
  try {
    return window.localStorage.getItem(CHOSEN_KEY) === '1';
  } catch {
    return true;
  }
}

export function setLang(code) {
  const next = DICT[code] ? code : 'en';
  try {
    window.localStorage.setItem(KEY, next);
    // Any deliberate selection (gate tap or switcher) counts as a choice, so the
    // first-open prompt never appears again.
    window.localStorage.setItem(CHOSEN_KEY, '1');
  } catch {
    /* storage blocked */
  }
  if (typeof window !== 'undefined') window.dispatchEvent(new Event(EVENT));
}

// Replace {name} tokens in a translated string with values from `vars`. Missing
// vars render as empty strings. Only used when a caller passes interpolation
// data; plain t('key') calls are unaffected.
function interpolate(str, vars) {
  if (!vars) return str;
  return String(str).replace(/\{(\w+)\}/g, (m, k) => (vars[k] != null ? String(vars[k]) : ''));
}

export function translate(lang, key, vars) {
  // Live override wins, then the language's built-in text, then the English
  // fallback, then the raw key. OVERRIDES is empty until loadOverrides() runs,
  // so with no overrides this resolves exactly as before.
  const s = OVERRIDES[lang]?.[key] ?? DICT[lang]?.[key] ?? DICT.en[key] ?? key;
  return interpolate(s, vars);
}

/**
 * Current language + a translator, re-rendering when the language changes in
 * this tab (custom event) or another tab (storage event). SSR-safe: the first
 * render is always 'en' on both server and client, so hydration never mismatches;
 * the stored choice is applied in the effect right after mount.
 */
export function useLang() {
  const [lang, setLangState] = useState('en');
  // Bumped whenever overrides load/change: the lang is unchanged but the
  // resolved strings are, so a distinct state value forces a re-render.
  const [, setTick] = useState(0);
  useEffect(() => {
    setLangState(getLang());
    const on = () => setLangState(getLang());
    const onOverride = () => setTick((n) => n + 1);
    window.addEventListener(EVENT, on);
    window.addEventListener('storage', on);
    window.addEventListener(OVERRIDE_EVENT, onOverride);
    return () => {
      window.removeEventListener(EVENT, on);
      window.removeEventListener('storage', on);
      window.removeEventListener(OVERRIDE_EVENT, onOverride);
    };
  }, []);
  const change = (code) => {
    setLang(code);
    setLangState(DICT[code] ? code : 'en');
  };
  return { lang, setLang: change, t: (key, vars) => translate(lang, key, vars) };
}
